// Package tools are not simulated: every output comes from tests/sandbox/record/vm-p5.txt (Ubuntu VM) or vm-p5-alma.txt (AlmaLinux 10).
const P5_UBU = T('הפלט הוקלט על שרת Ubuntu אמיתי. מה הודפס?', 'This was recorded on a real Ubuntu server. What was printed?');
const P5_ALMA = T('הפלט הוקלט על AlmaLinux 10 אמיתי (גרסה חינמית של RHEL 10). מה הודפס?', 'This was recorded on a real AlmaLinux 10 (a free twin of RHEL 10). What was printed?');
const p5Sudo = (...cmds) => cmds.flatMap(c => [c, `sudo ${c}`]);
const P5_WEB_OPTS = [['-d', '--name web', '-p 8080:80'], ['--name web', '-d', '-p 8080:80'], ['-d', '-p 8080:80', '--name web'], ['--name web', '-p 8080:80', '-d'], ['-p 8080:80', '-d', '--name web'], ['-p 8080:80', '--name web', '-d']];
const P5_RUN_WEB = p5Sudo(...['podman', 'docker'].flatMap(e => P5_WEB_OPTS.map(o => `${e} run ${o.join(' ')} nginx`)));

